mapper.select:
SELECT id, user_id, week_key, submitted, submitted_at
FROM weekly_reports
WHERE user_id = #{userId}
  AND week_key = #{weekKey}

SELECT id, user_id, week_key, submitted, submitted_at
FROM weekly_reports
WHERE id = #{reportId}

SELECT COALESCE(MAX(display_order), 0)
FROM report_items
WHERE weekly_report_id = #{reportId}
  AND status = #{status}

SELECT COALESCE(MAX(ri.display_order), 0)
FROM report_items ri
JOIN weekly_reports wr ON wr.id = ri.weekly_report_id
JOIN users u ON u.id = wr.user_id
WHERE (CASE WHEN ri.source_task_id IS NOT NULL THEN ri.source_team_id ELSE u.team_id END) = #{teamId}
  AND wr.week_key = #{weekKey}
  AND wr.submitted = TRUE
  AND ri.status = #{status}

SELECT ri.*, wr.user_id, u.name AS member_name, CASE WHEN ri.source_task_id IS NOT NULL THEN ri.source_team_id ELSE u.team_id END AS team_id, t.name AS team_name
FROM report_items ri
JOIN weekly_reports wr ON wr.id = ri.weekly_report_id
JOIN users u ON u.id = wr.user_id
LEFT JOIN teams t ON t.id = CASE WHEN ri.source_task_id IS NOT NULL THEN ri.source_team_id ELSE u.team_id END
WHERE (CASE WHEN ri.source_task_id IS NOT NULL THEN ri.source_team_id ELSE u.team_id END) = #{teamId}
  AND wr.week_key = #{weekKey}
  AND wr.submitted = TRUE
  AND ri.status = #{status}
ORDER BY ri.display_order, u.name, ri.id

SELECT rid.*
FROM report_item_details rid
WHERE rid.id = #{detailId}

mapper.update:
UPDATE report_items
SET status = #{status}, display_order = #{displayOrder}
WHERE id = #{itemId}

UPDATE report_items
SET display_order = #{displayOrder}
WHERE id = #{itemId}

UPDATE report_item_details
SET text = #{text},
    due_date = #{dueDate},
    cycle = #{cycle},
    display_order = #{displayOrder}
WHERE id = #{id}

UPDATE weekly_reports
SET submitted = TRUE, submitted_at = NOW()
WHERE id = #{reportId}

UPDATE weekly_reports
SET submitted = FALSE, submitted_at = NULL
WHERE id = #{reportId}

UPDATE weekly_reports
SET submitted = FALSE, submitted_at = NULL
WHERE id = #{reportId}

mapper.select:
SELECT id, team_id, week_key, submitted, submitted_at
FROM team_weekly_status
WHERE team_id = #{teamId}
  AND week_key = #{weekKey}

mapper.insert:
INSERT INTO weekly_confirmations(week_key, confirmed, confirmed_at, confirmed_by)
VALUES(#{weekKey}, TRUE, NOW(), #{confirmedBy})
ON DUPLICATE KEY UPDATE confirmed = TRUE, confirmed_at = NOW(), confirmed_by = #{confirmedBy}

mapper.update:
UPDATE weekly_confirmations
SET confirmed = FALSE, confirmed_at = NULL, confirmed_by = NULL
WHERE week_key = #{weekKey}
